function present(value) {
  return value !== undefined && value !== null && String(value).trim() !== '';
}

function cleanPhone(value) {
  if (!present(value)) return '';
  const text = String(value).trim();
  if (text.startsWith('+')) return '+' + text.slice(1).replace(/\D/g, '');
  return text.replace(/[^\d+]/g, '');
}

function bool(value) {
  return value === true || ['true', 'yes', '1', 'subscribed', 'ok'].includes(String(value ?? '').trim().toLowerCase());
}

function formatScheduledAt(value) {
  if (!present(value)) return '';
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return String(value);
  const pad = (part) => String(part).padStart(2, '0');
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())} ${pad(date.getHours())}:${pad(date.getMinutes())}:${pad(date.getSeconds())}`;
}

const payload = $json.body ?? $json;
const to = cleanPhone(payload.to ?? payload.phone ?? payload.recipient);
const message = String(payload.message ?? payload.text ?? payload.body ?? '').trim();
const channel = String(payload.channel ?? 'sms').trim().toLowerCase();
const scheduledAt = formatScheduledAt(payload.scheduledAt ?? payload.scheduled_at ?? '');
const consent = bool(payload.consent ?? payload.smsConsent ?? payload.optIn ?? payload.opt_in);
const allowedChannels = ['sms', 'whatsapp'];
const errors = [];

if (!to) errors.push('to is required');
if (!message) errors.push('message is required');
if (!consent) errors.push('consent must be true');
if (!allowedChannels.includes(channel)) errors.push('channel must be sms or whatsapp');
if (message.length > 1000) errors.push('message is too long');

return [{
  json: {
    valid: errors.length === 0,
    errors,
    to,
    message,
    channel,
    scheduledAt,
    source: payload.source ?? '',
    referenceId: payload.referenceId ?? payload.reference_id ?? '',
  },
}];
